import numpy as np


def mc_marginal(x, g, s, n_z, seed):
    z = np.random.default_rng(seed).uniform(-3, 3, n_z)
    d2 = ((np.asarray(x, dtype=float) - g(z)) ** 2).sum(axis=1)
    return float(np.mean(np.exp(-d2 / (2 * s * s)) / (2 * np.pi * s * s)))
